// Generated by Claude Code
package grading.feedback;

import grading.execution.TestCaseResult;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * Recognises a method the student has not written: its body is still the template's starter code,
 * which only returns a placeholder value. Its failed test cases need no other explanation.
 */
final class StarterCodeRule implements FeedbackRule {

    @Override
    public List<Feedback> apply(FeedbackContext context) {
        Map<String, List<TestCaseResult>> failedByMethod = new LinkedHashMap<>();
        for (TestCaseResult test : context.unexplainedFailures()) {
            FeedbackContext.methodName(test)
                    .ifPresent(name -> failedByMethod.computeIfAbsent(name, key -> new ArrayList<>()).add(test));
        }
        List<Feedback> feedback = new ArrayList<>();
        failedByMethod.forEach((name, tests) -> context.method(name)
                .filter(located -> located.file().isStarterCode(located.method()))
                .ifPresent(located -> {
                    List<Integer> returns = located.file().returns(located.method());
                    int line = returns.isEmpty() ? located.method().start() : returns.getFirst();
                    feedback.add(Feedback.at(context.questionId(), "Method not written", "`" + name
                            + "` is still the starter code, so it only returns the placeholder value and "
                            + FeedbackContext.testNumbers(tests).toLowerCase(Locale.ROOT)
                            + " failed. Write the method's code in place of the placeholder.",
                            located.file().at(line)));
                    context.explain(tests);
                }));
        return feedback;
    }
}
